type: spec
model: SDTM
domain: LB
keys: [ID, LBTESTCD]
input: {SRC: input.csv}
output: {path: output.csv, report: checks.csv, columns: [ID, LBTESTCD, LBDTC, LBORRES]}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
  - {name: LBTESTCD, type: str}
  - {name: LBDTC, type: str, derivation: SRC.DTC, submission: {data_type: DTC_TYPE, origins: [{type: Collected, source: Investigator}]}}
  - {name: LBORRES, type: str, derivation: SRC.RES, submission: {length: 20, origins: [{type: Collected, source: Investigator}], value_level: [{id: ONSET, where: {LBTESTCD: [ONSET]}, data_type: date}]}}
rows:
  - id: glucose
